-- tb/tb_fixed_pkg.vhd
-- Kernel bit-exact test: rsqrt_q, exp_q, sigmoid_q vs golden files
-- generated by ref/dump_luts.c from the same fx.h arithmetic.
library ieee; use ieee.std_logic_1164.all; use ieee.numeric_std.all;
use std.textio.all;
use work.fixed_pkg.all;

entity tb_fixed_pkg is end;

architecture sim of tb_fixed_pkg is
begin
  process
    file   f   : text;
    variable L : line;
    variable n, inq, outq, got : integer;
  begin

    -- ---- rsqrt ----
    file_open(f, "../mem/golden/kern_rsqrt.txt", read_mode);
    readline(f, L); read(L, n);
    for i in 0 to n - 1 loop
      readline(f, L);
      read(L, inq);
      read(L, outq);
      got := to_integer(rsqrt_q(to_signed(inq, 64), 12));
      assert got = outq
        report "rsqrt in=" & integer'image(inq) &
               " got " & integer'image(got) &
               " exp " & integer'image(outq)
        severity failure;
    end loop;
    file_close(f);

    -- ---- exp ----
    file_open(f, "../mem/golden/kern_exp.txt", read_mode);
    readline(f, L); read(L, n);
    for i in 0 to n - 1 loop
      readline(f, L);
      read(L, inq);
      read(L, outq);
      got := to_integer(exp_q(to_signed(inq, 64), 12));
      assert got = outq
        report "exp in=" & integer'image(inq) &
               " got " & integer'image(got) &
               " exp " & integer'image(outq)
        severity failure;
    end loop;
    file_close(f);

    -- ---- sigmoid ----
    file_open(f, "../mem/golden/kern_sigmoid.txt", read_mode);
    readline(f, L); read(L, n);
    for i in 0 to n - 1 loop
      readline(f, L);
      read(L, inq);
      read(L, outq);
      got := to_integer(sigmoid_q(to_signed(inq, 64), 12));
      assert got = outq
        report "sigmoid in=" & integer'image(inq) &
               " got " & integer'image(got) &
               " exp " & integer'image(outq)
        severity failure;
    end loop;
    file_close(f);

    report "PASS:fixed_pkg" severity note;
    std.env.finish;
  end process;
end;
